 $("pageContent").innerHTML='<div class="feed-create"><div><b>Есть чем поделиться?</b><small>Опубликуй текст или найди новых авторов</small></div><a class="primary feed-create-link" href="#/new">＋ Создать публикацию</a></div><div class="feed-layout"><section class="feed-main">'+filters()+(shown.length?shown.map(postCard).join(""):empty("Пока здесь пусто","Опубликуй первую запись или измени фильтры."))+'</section>'+side()+'</div>';
