function readLocalUsers(){try{return readLocalJSON("rh_local_users",{})}catch(e){return{}}}function currentFollows(){if(!S.user)return[];const key=S.user.username.toLowerCase(),graph=readLocalJSON("rh_follow_graph",{}),legacyKey=Object.keys(graph).find(k=>k.toLowerCase()===key);if(legacyKey&&Array.isArray(graph[legacyKey])){if(legacyKey!==key){graph[key]=graph[legacyKey];delete graph[legacyKey];try{localStorage.setItem("rh_follow_graph",JSON.stringify(graph))}catch(e){}}return graph[key]}const legacy=readLocalJSON("rh_follows",[]),initial=Object.keys(graph).length?[]:legacy;graph[key]=initial;try{localStorage.setItem("rh_follow_graph",JSON.stringify(graph))}catch(e){}return initial}function profileFollowCounts(username){const graph=readLocalJSON("rh_follow_graph",{}),key=String(username||"").toLowerCase(),entry=Object.entries(graph).find(([name])=>name.toLowerCase()===key),following=entry&&Array.isArray(entry[1])?entry[1].length:0,followers=Object.values(graph).filter(list=>Array.isArray(list)&&list.some(name=>String(name).toLowerCase()===key)).length;return{following,followers}}
function showFollowList(username,type){const graph=readLocalJSON("rh_follow_graph",{}),key=String(username||"").toLowerCase();let names=[];if(type==="following"){const entry=Object.entries(graph).find(([name])=>name.toLowerCase()===key);names=entry&&Array.isArray(entry[1])?entry[1]:[]}else names=Object.entries(graph).filter(([,list])=>Array.isArray(list)&&list.some(name=>String(name).toLowerCase()===key)).map(([name])=>name);const unique=[...new Set(names.map(String))],users=unique.map(name=>readLocalUsers()[name.toLowerCase()]||DEMO_USERS.find(u=>u.username.toLowerCase()===name.toLowerCase())).filter(Boolean);modal(type==="following"?"Подписки":"Подписчики","Участники профиля",users.length?'<div class="follow-list">'+users.map(u=>'<button class="follow-list-item" data-action="profile" data-user="'+esc(u.username)+'">'+avatar(u,38)+'<span><b>'+esc(u.display_name||u.username)+'</b><small>@'+esc(u.username)+'</small></span><span class="follow-list-arrow">›</span></button>').join("")+'</div>':empty(type==="following"?"Пока нет подписок":"Пока нет подписчиков","Список появится, когда участники начнут взаимодействовать."),'<button class="secondary" data-action="close">Закрыть</button>')}
async function passwordDigest(password,salt){if(!window.crypto?.subtle)throw Error("Браузер не поддерживает безопасное локальное хранение пароля. Обнови Safari.");const key=await crypto.subtle.importKey("raw",new TextEncoder().encode(password),"PBKDF2",false,["deriveBits"]);const bits=await crypto.subtle.deriveBits({name:"PBKDF2",salt:new TextEncoder().encode(salt),iterations:120000,hash:"SHA-256"},key,256);return [...new Uint8Array(bits)].map(x=>x.toString(16).padStart(2,"0")).join("")}
async function localAuth(mode,username,password,displayName){const users=readLocalUsers(),key=username.toLowerCase();if(mode==="register"){if(key==="raher")throw Error("Имя Raher зарезервировано за главным администратором.");if(password.length<6)throw Error("Пароль должен содержать минимум 6 символов.");if(users[key])throw Error("Этот логин уже зарегистрирован в этом браузере.");const salt=[...crypto.getRandomValues(new Uint8Array(16))].map(x=>x.toString(16).padStart(2,"0")).join("");users[key]={username,display_name:displayName||username,bio:"",role:"user",salt,pass_hash:await passwordDigest(password,salt),created_at:new Date().toISOString(),status:"active"};try{localStorage.setItem("rh_local_users",JSON.stringify(users))}catch(e){delete users[key];throw Error("Не удалось создать аккаунт: хранилище браузера заполнено")}}else{const u=users[key];if(!u)throw Error("Локальный аккаунт не найден. Сначала зарегистрируйся.");if(u.status==="banned")throw Error("Аккаунт заблокирован администратором.");if(await passwordDigest(password,u.salt)!==u.pass_hash)throw Error("Неверный логин или пароль.");}const u=users[key];S.user={username:u.username,display_name:u.display_name,bio:u.bio||"",avatar:u.avatar||"",role:u.role||"user",created_at:u.created_at,local:true};S.token="";S.demoMode=true;try{localStorage.removeItem("rh_token")}catch(e){}try{localStorage.setItem("rh_local_session",key)}catch(e){S.user=null;throw Error("Аккаунт сохранён, но не удалось открыть сессию. Освободи место в хранилище и войди снова.")}close();topbar();toast(mode==="register"?"Локальный аккаунт создан!":"С возвращением!");go("feed")}
function auth(mode){modal(mode==="login"?"Вход":"Регистрация","Аккаунт RH Media",'<form id="authForm"><div class="field"><label>Логин</label><input id="authName" required minlength="3" maxlength="24" autocomplete="username"></div><div class="field"><label>Пароль</label><input id="authPass" type="password" required minlength="6" maxlength="128" autocomplete="'+(mode==="login"?"current-password":"new-password")+'"></div>'+(mode==="register"?'<div class="field"><label>Отображаемое имя</label><input id="authDisplay" maxlength="32" placeholder="Как тебя называть"></div>':"")+(S.demoMode?'<div class="local-auth-note">Регистрация в локальном режиме: аккаунт сохранится только в этом браузере на этом устройстве.</div>':"")+'<div id="authError" class="danger"></div></form>','<button class="secondary" data-action="close">Отмена</button><button class="primary" data-action="submit-auth" data-mode="'+mode+'">'+(mode==="login"?"Войти":"Создать аккаунт")+'</button>')}
async function submitAuth(mode){
 const username=$("authName").value.trim(),password=$("authPass").value,displayName=$("authDisplay")?.value.trim()||username;
 if(!/^[a-zA-Z0-9_.-]{3,24}$/.test(username))return $("authError").textContent="Логин: 3–24 символа, латиница, цифры, точка, дефис или _.";
 if(password.length<6)return $("authError").textContent="Пароль должен содержать минимум 6 символов.";
 try{const d=await api("/api/"+(mode==="login"?"login":"register"),{method:"POST",body:JSON.stringify({username,password,display_name:displayName})});
 S.token=d.token;localStorage.setItem("rh_token",S.token);S.user=d.user;S.demoMode=false;close();topbar();toast(mode==="register"?"Аккаунт создан!":"С возвращением!");go("feed");
 }catch(e){$("authError").textContent=e.message}
}
function needAuth(){if(S.user&&S.token)return true;auth("login");return false}
function newPost(){if(!needAuth())return;modal("Новая публикация","Пока доступны текстовые публикации. Для фото, видео и аудио нужно отдельное файловое хранилище.",'<div class="field"><label>Текст публикации</label><textarea id="caption" maxlength="5000" placeholder="О чём хочешь рассказать?"></textarea></div><div class="field"><label>Медиафайлы</label><input id="files" type="file" multiple accept="image/*,video/*,audio/*" disabled><small class="field-note">Загрузка файлов временно отключена. Текстовые публикации сохраняются в облачной базе.</small></div><div class="field"><label>Видимость</label><select id="visibility"><option value="public">Всем</option><option value="unlisted">По ссылке</option></select></div><div id="postError" class="danger"></div>','<button class="secondary" data-action="close">Отмена</button><button class="primary" data-action="publish">Опубликовать</button>')}
async function publish(){const files=[...$("files").files],caption=$("caption").value.trim();if(files.length)return $("postError").textContent="Загрузка изображений, видео и аудио пока недоступна: файловое хранилище не входит в текущую конфигурацию Cloudflare. Опубликуй текст без файлов.";if(files.length)return $("postError").textContent="Загрузка медиафайлов пока не подключена. Опубликуй текстовую запись.";if(!caption)return $("postError").textContent="Добавь текст публикации.";if(files.length>10)return $("postError").textContent="Максимум 10 файлов.";if(S.demoMode){const configuredLimit=Number(readLocalJSON("rh_admin_settings",{}).uploadLimit)||10,uploadLimitBytes=Math.max(1,Math.min(100,configuredLimit))*1024*1024,totalSize=files.reduce((sum,f)=>sum+f.size,0);if(totalSize>uploadLimitBytes)return $("postError").textContent="Общий размер файлов превышает установленный лимит "+Math.max(1,Math.min(100,configuredLimit))+" МБ.";const media=[];try{for(const f of files){if(!/^(image|video|audio)\//i.test(f.type))return $("postError").textContent="Поддерживаются только изображения, видео и аудио.";if(f.size>uploadLimitBytes)return $("postError").textContent="Размер файла превышает установленный лимит "+Math.max(1,Math.min(100,configuredLimit))+" МБ.";const url=await new Promise((resolve,reject)=>{const rd=new FileReader();rd.onload=()=>typeof rd.result==="string"?resolve(rd.result):reject(new Error("Файл не удалось прочитать"));rd.onerror=()=>reject(new Error("Ошибка чтения файла"));rd.onabort=()=>reject(new Error("Чтение файла прервано"));try{rd.readAsDataURL(f)}catch(e){reject(e)}});media.push({name:f.name,mime:f.type,url})}}catch(e){return $("postError").textContent="Не удалось обработать файл: "+(e.message||"попробуй другой файл.")}const p={id:"local-"+Date.now(),user:{username:S.user.username,display_name:S.user.display_name,role:S.user.role},caption,created_at:new Date().toISOString(),likes:0,comments:0,views:0,media};try{localStorage.setItem("rh_demo_posts",JSON.stringify([p,...localPosts()]))}catch(e){return $("postError").textContent="Не удалось сохранить публикацию: хранилище браузера заполнено. Уменьши размер файлов или освободи место."}close();toast("Публикация сохранена локально");feed();return}try{const media=[];for(const f of files){if(f.size>200*1024*1024)throw Error("Файл больше 200 МБ: "+f.name);const fd=new FormData();fd.append("file",f);const r=await fetch(API+"/api/upload",{method:"POST",headers:{Authorization:"Bearer "+S.token},body:fd}),d=await r.json();if(!r.ok)throw Error(d.error||"Ошибка загрузки");media.push(d.file)}await api("/api/posts",{method:"POST",body:JSON.stringify({caption,media,visibility:$("visibility").value})});close();toast("Публикация добавлена");go("feed")}catch(e){$("postError").textContent=e.message}}
