async function compressAvatar(file){
 const fail=message=>{throw Error(message)};
 if(!file||!file.type||!file.type.startsWith("image/"))fail("Выбери файл изображения (image/*).");
 if(file.size>10*1024*1024)fail("Файл слишком большой. Максимальный размер — 10 МБ.");
 const objectUrl=URL.createObjectURL(file);
 try{
  const image=await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(Error("Не удалось открыть изображение. Выбери другой файл."));img.src=objectUrl});
  const width=image.naturalWidth||image.width,height=image.naturalHeight||image.height;
  if(!width||!height)fail("Не удалось определить размеры изображения.");
  const scale=Math.min(1,512/Math.max(width,height)),w=Math.max(1,Math.round(width*scale)),h=Math.max(1,Math.round(height*scale));
  const canvas=document.createElement("canvas");canvas.width=w;canvas.height=h;
  const ctx=canvas.getContext("2d");if(!ctx)fail("Браузер не поддерживает обработку изображений.");
  ctx.drawImage(image,0,0,w,h);
  const blob=await new Promise(resolve=>canvas.toBlob(resolve,"image/webp",0.85));
  if(!blob)fail("Не удалось сжать изображение. Попробуй другой файл.");
  const output=blob.type==="image/webp"?blob:await new Promise(resolve=>canvas.toBlob(resolve,"image/jpeg",0.85));
  if(!output)fail("Не удалось подготовить сжатую фотографию.");
  return await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>typeof reader.result==="string"?resolve(reader.result):reject(Error("Не удалось прочитать сжатую фотографию"));reader.onerror=()=>reject(Error("Ошибка чтения сжатого изображения"));reader.readAsDataURL(output)});
 }finally{URL.revokeObjectURL(objectUrl)}
}
function previewAvatarFile(file){
 const error=$("profileError"),preview=$("avatarPreview");if(error)error.textContent="";
 if(!file||!preview)return;
 if(!file.type||!file.type.startsWith("image/")){if(error)error.textContent="Неподдерживаемый файл. Выбери изображение (image/*).";return}
 if(file.size>10*1024*1024){if(error)error.textContent="Файл слишком большой. Максимальный размер — 10 МБ.";return}
 const url=URL.createObjectURL(file);
 preview.innerHTML='<img src="'+esc(url)+'" alt="Предпросмотр аватара" class="avatar-preview-image">';
 const image=preview.querySelector("img");image.onload=()=>URL.revokeObjectURL(url);image.onerror=()=>{URL.revokeObjectURL(url);if(error)error.textContent="Не удалось открыть это изображение."};
}
