if(parsed.rh_notification_prefs&&Object.entries(parsed.rh_notification_prefs).some(([k,v])=>!["sound","likes","comments","followers","messages"].includes(k)||typeof v!=="boolean"))throw Error("Некорректные настройки уведомлений в резервной копии.");
if(parsed.rh_demo_posts)for(const p of parsed.rh_demo_posts){if(!isObj(p)||typeof p.id!=="string"||p.id.length>128||!isObj(p.user)||!validName(p.user.username)||typeof p.caption!=="string"||p.caption.length>5000||!Array.isArray(p.media)||p.media.length>10||p.media.some(m=>!isObj(m)||typeof m.name!=="string"||typeof m.mime!=="string"||typeof m.url!=="string"||safeMediaUrl(m.url)!==m.url))throw Error("Повреждена публикация в резервной копии.")}
