if(parsed.rh_local_messages)for(const m of parsed.rh_local_messages){if(!isObj(m)||!validName(m.from)||!validName(m.to)||typeof m.text!=="string"||m.text.length>2000||!validTime(m.created_at))throw Error("Повреждено личное сообщение в резервной копии.")}
if(parsed.rh_local_notifications)for(const n of parsed.rh_local_notifications){if(!isObj(n)||!validName(n.username)||!["like","comment","follow","message"].includes(n.type)||typeof n.text!=="string"||n.text.length>500||n.actor!=null&&typeof n.actor!=="string"||n.read!=null&&typeof n.read!=="boolean")throw Error("Повреждено уведомление в резервной копии.")}
if(parsed.rh_local_comments)for(const [postId,list] of Object.entries(parsed.rh_local_comments)){if(typeof postId!=="string"||!Array.isArray(list)||list.some(c=>!isObj(c)||!validName(c.username)||typeof c.body!=="string"||c.body.length>1500))throw Error("Повреждены комментарии в резервной копии.")}
if(parsed.rh_follows&&parsed.rh_follows.some(x=>!validName(x)))throw Error("Повреждён список подписок.")
